describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("converts text with punctuation to slug", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
  });

  test("collapses multiple spaces", () => {
    expect(slugify("Foo  Bar")).toBe("foo-bar");
  });

  test("collapses multiple underscores", () => {
    expect(slugify("Foo__Bar")).toBe("foo-bar");
  });

  test("collapses repeated hyphens", () => {
    expect(slugify("a---b")).toBe("a-b");
  });

  test("trims leading and trailing hyphens", () => {
    expect(slugify("-hello-world-")).toBe("hello-world");
  });

  test("normalizes mixed case", () => {
    expect(slugify("HeLLo WoRLd")).toBe("hello-world");
  });

  test("removes special characters from alphanumeric text", () => {
    expect(slugify("Test123!@#456")).toBe("test123456");
  });

  test("handles empty string", () => {
    expect(slugify("")).toBe("");
  });

  test("handles only special characters", () => {
    expect(slugify("!@#$%")).toBe("");
  });

  test("handles complex real-world example", () => {
    expect(slugify("  Hello,  World!__Test---123  ")).toBe("hello-world-test-123");
  });
});

